/**
 * Mirrors `dashboard.schema.json`, generated by the Python `export` command from
 * `DashboardData.model_json_schema()`. Datetimes are ISO 8601 strings, dates are `YYYY-MM-DD`.
 */

export interface SourceInfo {
  /** Identifier of the meter. */
  device_id: string;
  /** First minute of data, in UTC. */
  period_start_utc: string;
  /** Last minute of data, in UTC. */
  period_end_utc: string;
  /** IANA zone used for local days and display. */
  timezone: string;
}

export interface PeakPower {
  /** Peak power, in kW. */
  power_kw: number;
  /** Start of the peak minute, in UTC. */
  timestamp_utc: string;
  /** Same instant in the local time zone. */
  timestamp_local: string;
}

export interface ConsumptionSummary {
  /** Energy over all observed minutes, in kWh. */
  total_energy_kwh: number;
  /** Mean daily energy over complete local days only, in kWh. */
  average_daily_energy_kwh: number;
  /** Number of local days used for the daily average. */
  complete_days: number;
  peak: PeakPower;
  /** Base load: low percentile of minute power, in W. */
  base_load_w: number;
  /** Local day with the highest energy. */
  peak_day: string;
  /** Energy of the peak day, in kWh. */
  peak_day_energy_kwh: number;
}

export interface HourlyEnergyPoint {
  /** Start of the hour, in UTC. */
  start_utc: string;
  /** Energy of the observed minutes, in kWh. */
  energy_kwh: number;
  /** Minutes with data in this hour (60 = complete). */
  observed_minutes: number;
}

export interface DailyEnergyPoint {
  /** Local calendar day. */
  day: string;
  /** Energy of the observed minutes, in kWh. */
  energy_kwh: number;
  /** Minutes with data in this day. */
  observed_minutes: number;
  /** Minutes in the local day (1380, 1440 or 1500). */
  expected_minutes: number;
}

export interface ProfilePoint {
  /** Local hour of day, 0 to 23. */
  hour: number;
  /** Mean power over all observed minutes, in W. */
  mean_power_w: number;
  /** Lower edge of the band (25th percentile by default): across days, the mean power of this hour, in W. */
  band_lower_power_w: number;
  /** Upper edge of the band (75th percentile by default): across days, the mean power of this hour, in W. */
  band_upper_power_w: number;
}

export interface DailyProfile {
  /** Monday to Friday. */
  weekday: ProfilePoint[];
  /** Saturday and Sunday. */
  weekend: ProfilePoint[];
  /** Number of local weekdays with at least one reading, averaged in `weekday`. */
  weekday_days: number;
  /** Number of local weekend days with at least one reading, averaged in `weekend`. */
  weekend_days: number;
}

export interface DataGap {
  /** First missing minute, in UTC. */
  start_utc: string;
  /** Last missing minute, in UTC. */
  end_utc: string;
  /** Number of missing minutes. */
  missing_minutes: number;
}

export interface DataQuality {
  /** Minutes between first and last reading, inclusive. */
  expected_minutes: number;
  /** Minutes with a reading. */
  observed_minutes: number;
  /** Observed over expected minutes, in percent. */
  coverage_pct: number;
  /** Only gaps longer than this are listed. */
  gap_threshold_minutes: number;
  /** Gaps longer than the threshold, chronological. */
  gaps: DataGap[];
}

export interface VoltageSettings {
  /** Nominal voltage, in V. */
  nominal_v: number;
  /** Tolerance around the nominal value, in percent. */
  tolerance_pct: number;
  /** Out-of-range runs of one direction separated by fewer minutes are merged. */
  excursion_merge_minutes: number;
  /** Lower limit, in V. A voltage equal to it is compliant. */
  lower_v: number;
  /** Upper limit, in V. A voltage equal to it is compliant. */
  upper_v: number;
}

export interface VoltageSummary {
  /** Lowest minute voltage, in V. */
  min_v: number;
  /** Highest minute voltage, in V. */
  max_v: number;
  /** Mean minute voltage, in V. */
  mean_v: number;
  /** Minutes with a usable voltage (above 0 V). */
  measured_minutes: number;
  /** Minutes between the first and last reading without a usable voltage. */
  missing_minutes: number;
  /** Measured over expected minutes, in percent. */
  coverage_pct: number;
  /** Measured minutes strictly below the lower limit. */
  time_below_range_min: number;
  /** Measured minutes strictly above the upper limit. */
  time_above_range_min: number;
  /** Measured minutes within the limits (inclusive), in percent of measured ones. */
  pct_time_in_range: number;
  /** Number of excursions, after merging close runs. */
  excursion_count: number;
  /** True when no measured minute is out of range. */
  is_compliant: boolean;
}

export interface VoltageDailyPoint {
  /** Local calendar day. */
  day: string;
  /** Lowest minute voltage of the day, in V; `null` on a day without measurement. */
  min_v: number | null;
  mean_v: number | null;
  max_v: number | null;
  /** Minutes with a usable voltage in the day. */
  measured_minutes: number;
  /** Measured minutes outside the limits. */
  minutes_out_of_range: number;
}

export interface VoltageHourlyPoint {
  /** Start of the hour, in UTC. */
  start_utc: string;
  min_v: number;
  mean_v: number;
  max_v: number;
}

export type VoltageDirection = 'below' | 'above';

export interface VoltageExcursion {
  /** First out-of-range minute, in Europe/Paris. */
  start_local: string;
  /** Last out-of-range minute, in Europe/Paris. */
  end_local: string;
  /** Minutes from the first to the last out-of-range minute. */
  duration_min: number;
  /** Out-of-range measured minutes in the excursion. */
  out_of_range_minutes: number;
  direction: VoltageDirection;
  /** Lowest (below) or highest (above) voltage, in V. */
  worst_value_v: number;
}

export interface VoltageQualityReport {
  settings: VoltageSettings;
  summary: VoltageSummary;
  /** One point per local day, chronological. */
  daily: VoltageDailyPoint[];
  /** Chronological. */
  excursions: VoltageExcursion[];
  /** Downsampled series, one point per hour. */
  hourly: VoltageHourlyPoint[];
}

export interface DashboardData {
  source: SourceInfo;
  summary: ConsumptionSummary;
  hourly: HourlyEnergyPoint[];
  daily: DailyEnergyPoint[];
  daily_profile: DailyProfile;
  quality: DataQuality;
  voltage: VoltageQualityReport;
}

/** What the UI can be showing while `dashboard.json` is being obtained. */
export type DashboardState =
  | { kind: 'loading' }
  | { kind: 'error' }
  | { kind: 'empty' }
  | { kind: 'ready'; data: DashboardData };
